class Title extends Text [ fontWeight = semibold, textColor = { this.$provided("theme").text } ]

class Muted extends Text [ textColor = { this.$provided("theme").textMuted } ]

class Mono extends Text [ fontFamily = { this.root.mono } ]

// a component tab in the left rail — selection is one App attribute
// (`app.selected`, the class name); a tab lights when it matches and writes
// the location on click, so the whole navigator is one string

class ClassTab extends View [ width = 100%, height = 30, cornerRadius = 6,
    cname:   string = "",
    lit: boolean = { this.root.mode == "reference" && this.root.selected == classroot.cname },
    fill = { this.lit ? this.$provided("theme").sel : this.hovered ? this.$provided("theme").control : null },
    link = { "#reference/" + this.cname },
    onClick()     { this.root.goRef(classroot.cname) },
    lbl: Mono [ x = 24, y = 7, fontSize = 14, wrap = false,
        text = { classroot.cname },
        textColor = { classroot.lit ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


/* A rail group's head — the line that folds it. Untouched, a group is OPEN when
   it holds the current page and closed otherwise, so the rail always shows where
   you are. A click overrides that, and THE TWO OVERRIDES DO NOT EXPIRE ALIKE:

   - OPENED BY THE READER: permanent. What the reader opened stays open through
     every navigation. The rail's contents must not move under the hand that is
     clicking in it — an outline that re-folds itself on every click makes the
     reader hunt for a row that was under the cursor a moment ago.
   - SHUT BY THE READER: keyed to the page it was made on, which is what it takes
     to shut a group the rail is auto-opening BECAUSE it holds the current page.
     Navigating away retires it, so a group shut once is not shut forever.

   One class serves the guide's parts, the language's form groups, and the class
   groups alike. */

class FoldHead extends View [ width = 100%, height = 28, cornerRadius = 6, cursor = "pointer",
    label:    string  = "",
    contains: boolean = false,             // does this group hold the current page?
    opened:   boolean = false,             // it has been open — this does not expire
    shut:     boolean = false,             // the reader shut it, …
    shutAt:   string  = "",                // … keyed by the page it was made on
    open:     boolean = { (classroot.shut && classroot.shutAt == this.root.page) ? false
        : classroot.opened || classroot.contains },

    // ONCE OPEN, IT STAYS OPEN. A group the rail opened because it held the page
    // latches here, so navigating out of it does not fold it back up under the
    // reader — without this the rail still jumps on every click, just by one
    // group instead of all of them. Only a click closes anything.
    // (`onInit` as well as `onChange`: the group holding the page the reader
    // LANDED on has `contains` true from construction, and a value that starts
    // true never changes, so no change event would ever latch it.)

    trackChanges = ["contains"],
    onInit() { if (this.contains) this.opened = true },
    onChange(e: ChangeEvent) { if (this.contains) { this.opened = true; this.shut = false } },
    fill = { this.hovered ? this.$provided("theme").control : null },
    onClick() {
      if (this.open) { this.opened = false; this.shut = true; this.shutAt = this.root.page }
      else { this.opened = true; this.shut = false }
        },
    mark: Mono [ x = 8, y = 8, fontSize = 10, wrap = false, textColor = { this.$provided("theme").textMuted },
        text = { classroot.open ? "\u25BC" : "\u25B6" } ],
    lbl: Text [ x = 24, y = 6, fontSize = 14, fontWeight = semibold, wrap = false,
        text = { classroot.label },
        textColor = { classroot.contains ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


// one topic of classes in the reference rail (model.classGroups — extract's CLASS_GROUPS)

class ClassGroup extends View [ width = 100%,
    layout: SimpleLayout [ axis = y, spacing = 2 ],
    head: FoldHead [ label = { "" + this.$data(["name"]) },
        contains = { this.root.mode == "reference" && (this.$data(["classes"])).some(c => c.name == this.root.selected) } ],
    body: View [ width = 100%, visible = { classroot.head.open },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        ClassTab [ datapath = :classes[], cname = :name ],
        g: View [ height = 6 ]
        ]
    ]


