/*
## The live example

An editable source field beside a running preview — the same machinery as the
homepage's editable demos: a `TextInput` seeded from the demo source that
republishes edits on `app.liveSource`, and an `AppIsland` the host mounts
the compiled child app into. Both are keyed by the class name: the editor
seeds from `app.demoSources[<Class>]` (the server populates this from
apps/docs/demos/), and the island's `program = <Class>` is what the host
wires.
*/

class DocField extends TextInput [ multiline = true, spellcheck = false, wrap = false,
    fontFamily = { this.root.mono }, fontSize = { 13 * this.root.fontScale }, textColor = { this.$provided("theme").code },   // 13 = the house code size (PROSE.codeSize)
    editName: string = "",
    src: string = "",

    // Seed the field from the demo source once the subtree exists. (TextInput's
    // `initial` yielding-seed can't be used here: its attach-time guard fires
    // before this field's datapath-sourced `src` constraint is bound, so the seed
    // is skipped. An `onInit` write lands after the model has resolved `src`, and —
    // being an author write, not a constraint — leaves the field freely editable.)

    onInit() { this.text = this.src },
    onInput() { this.root.liveCard = this.editName; this.root.liveSource = this.text }
    ]


// Rendered by datapath replication over the class's 0-or-1 `example` array, so the
// whole island (editor + preview) is constructed only for classes that ship a demo.

class Example extends View [ width = 100%,
    cname:  string = { this.$data(["name"]) },
    elines: number = { this.$data(["lines"]) },
    esrc:   string = { this.$data(["source"]) },
    estage: number = { this.$data(["stageH"]) || 250 },   // extractor-measured stage height — the frame fits the settled app
    live:   boolean = false,             // the parent gates the preview: it mounts only when this is true

    // this island's edit failed to compile (host publishes the report; see RunIsland)

    broken: boolean = { this.root.liveCard == this.cname && this.root.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block below, no gap

    // the example's own title and lead (from the demo file's opening comment)

    head: View [ width = 100%,
        layout: SimpleLayout [ axis = y, spacing = 6 ],
        Title [ fontSize = { 16 * this.root.fontScale }, text = { "" + this.$data(["title"]) } ],
        lead: Markdown [ width = 100%, visible = { ("" + this.$data(["lead"])) != "" }, lineHeight = 1.55,
            bodyColor = { this.$provided("theme").refDim }, fontScale = { this.root.fontScale }, dark = { this.root.darkUI }, text = { "" + this.$data(["lead"]) } ],
        gap: View [ height = 6 ]
        ],

    // the editable source card — coheres with a static code block (the same
    // `chipBg` tint, 8px radius, 13px code face) but is marked live/editable by an
    // amber left bar + label, where a read-only block carries the teal `codeRule`.

    panel: View [ width = 100%, fill = { this.$provided("theme").chipBg },
        height = { Math.min(classroot.elines * 15 * this.root.fontScale + 105, 900) },   // 15px/line measured; field pad + 60/8 chrome
        bar:   View [ x = 0, y = 0, width = 3, height = 100%, fill = { classroot.broken ? this.$provided("theme").errBar : this.$provided("theme").live } ],
        fname: Mono [ x = 18, y = 10, fontSize = { 11 * this.root.fontScale }, fontWeight = semibold, textColor = { this.$provided("theme").strong },
            text = { classroot.cname + ".declare" } ],

        // the marker is an inverted chip — the amber accent as fill, dark letters —
        // so "live/editable" reads at a glance, distinct from a read-only block

        tag:   View [ y = 7, height = 17, cornerRadius = 3, fill = { this.$provided("theme").live }, x = { parent.width - this.width - 14 },
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = { this.$provided("theme").liveInk },
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert — restore the pristine source and republish (see RunIsland)

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, this.$provided("theme").line) },
            x = { parent.tag.x - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { this.hovered ? this.$provided("theme").control : null },
            onClick() { classroot.panel.field.text = classroot.esrc
                        this.root.liveCard = classroot.cname
                        this.root.liveSource = classroot.esrc },
            rlbl: Text [ x = 8, y = 3, fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? this.$provided("theme").text : this.$provided("theme").textMuted }, text = "Revert" ]
            ],

        // a line of breathing room below the label before the code starts

        hair:  View [ x = 18, y = 51, width = { parent.width - 30 }, height = 1, fill = { this.$provided("theme").line } ],
        field: DocField [ x = 18, y = 60, width = { parent.width - 30 }, height = { parent.height - 68 },
            editName = { classroot.cname }, src = { classroot.esrc } ]
        ],

    // the compile report at the island (see RunIsland — same teaching surface)

    err: View [ width = 100%, fill = { this.$provided("theme").errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = 100%, fill = { this.$provided("theme").errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = { this.root.mono }, fontSize = { 12 * this.root.fontScale },
            textColor = { this.$provided("theme").errText }, text = { this.root.liveReport } ]
        ],

    // the live preview island — the host mounts the compiled child app here. The slot
    // is live ONLY while the parent says so (`live`), so exactly one preview (the one
    // on the visible page) compiles at a time, even though every page is constructed.

    // The running app sits inset in the tinted box exactly as the code field
    // above it does — same 18 left, 12 right — so the demo reads as a card on
    // the page rather than paint running to the edge. The box carries the inset
    // in its own height, so the app keeps the height the extractor measured.

    stage: View [ width = 100%, height = { classroot.estage + 52 }, fill = { this.$provided("theme").chipBg },

        // the app's own card, inset in the tinted box exactly as the code field
        // above it is — and the app sits inset again inside the card, so its
        // content has the same breathing room the code has

        card: View [ x = 18, y = 14, width = { parent.width - 30 }, height = { parent.height - 28 },
            cornerRadius = 8, fill = { this.$provided("theme").surface },
            run: AppIsland [ x = 12, y = 12, width = { parent.width - 24 }, height = { parent.height - 24 },
                program = { classroot.live ? classroot.cname : "" } ]
            ],

        // a blue rule (a darker shade of the chipBg box tint) divides the code above from the
        // running app below; the gold spine (drawn OVER both) continues the code's gold left bar
        // down the preview, same x/width

        divider: View [ x = 0, y = 0, width = 100%, height = 2, fill = { this.$provided("theme").rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = 100%, fill = { this.$provided("theme").live } ]
        ]
    ]


/*
## Inline examples, woven through the prose

Every `declare` code fence in any prose that compiles (as-is, or wrapped in
`App […]`) becomes a `RunIsland`: the source above, its live preview below —
edit and it re-runs. The extractor wrote its source to
`apps/docs/demos/<id>.declare`, so the host seeds and mounts it exactly
like the homepage's demos. `live` (threaded from the page) keeps the
preview's slot empty until its page is the one on screen, so only the visible
page's islands ever compile.
*/

class RunIsland extends View [ width = 100%,
    rid:    string  = { this.$data(["id"]) },
    rsrc:   string  = { this.$data(["source"]) },
    rlines: number  = { this.$data(["lines"]) },
    rstage: number  = { this.$data(["stageH"]) || 200 },   // extractor-measured stage height — the frame fits the settled app
    live:   boolean = false,

    // this island's edit is the one that failed to compile — the host publishes the
    // report on app.liveReport (cleared by a clean compile), keyed by app.liveCard

    broken: boolean = { this.root.liveCard == this.rid && this.root.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block, no gap

    // same code-box grammar as a static block (chipBg tint, 8px radius, 13px face),
    // marked live/editable by the amber bar + label (a read-only block is teal).

    // height: measured 15px/line at the 13px code face, plus the field's ~20px
    // padding and the 46+8 header/footer chrome — so the code fits without an
    // inner scrollbar up to the cap

    editor: View [ width = 100%, fill = { this.$provided("theme").chipBg },
        height = { Math.min(classroot.rlines * 15 * this.root.fontScale + 93, 900) },
        bar:  View [ x = 0, y = 0, width = 3, height = 100%, fill = { classroot.broken ? this.$provided("theme").errBar : this.$provided("theme").live } ],
        tag:  View [ x = 18, y = 7, height = 17, cornerRadius = 3, fill = { this.$provided("theme").live },
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = { this.$provided("theme").liveInk },
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert restores the pristine source and republishes it — the way back the
        // guide owes a reader it just told to break something

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, this.$provided("theme").line) },
            x = { parent.width - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { this.hovered ? this.$provided("theme").control : null },
            onClick() { classroot.editor.field.text = classroot.rsrc
                        this.root.liveCard = classroot.rid
                        this.root.liveSource = classroot.rsrc },
            rlbl: Text [ x = 8, y = 3, fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? this.$provided("theme").text : this.$provided("theme").textMuted }, text = "Revert" ]
            ],
        hint: Muted [ y = 9, fontSize = { 11 * this.root.fontScale }, italic = true, text = "runs live below ↓",
            x = { parent.rev.x - this.width - 12 } ],

        // a line of breathing room below the label before the code starts

        field: DocField [ x = 18, y = 46, width = { parent.width - 30 }, height = { parent.height - 54 },
            editName = { classroot.rid }, src = { classroot.rsrc } ]
        ],

    // the compile report, at the island — the diagnostic is a teaching surface, so a
    // broken edit shows its error right here (the last good render stays below it)

    err: View [ width = 100%, fill = { this.$provided("theme").errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = 100%, fill = { this.$provided("theme").errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = { this.root.mono }, fontSize = { 12 * this.root.fontScale },
            textColor = { this.$provided("theme").errText }, text = { this.root.liveReport } ]
        ],

    // inset to match the code field above it, as the reference's Example is

    stage: View [ width = 100%, height = { classroot.rstage + 52 }, fill = { this.$provided("theme").chipBg },
        card: View [ x = 18, y = 14, width = { parent.width - 30 }, height = { parent.height - 28 },
            cornerRadius = 8, fill = { this.$provided("theme").surface },
            run: AppIsland [ x = 12, y = 12, width = { parent.width - 24 }, height = { parent.height - 24 },
                program = { classroot.live ? classroot.rid : "" } ]
            ],
        divider: View [ x = 0, y = 0, width = 100%, height = 2, fill = { this.$provided("theme").rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = 100%, fill = { this.$provided("theme").live } ]
        ]
    ]


// one prose segment — a run of Markdown text OR (0-or-1) a runnable island. A code
// block that didn't compile stays folded into the Markdown as a static code fence.
// `tone`/`lead` let a caller dim the prose (the reference runs dimmer than the guide).

class Block extends View [ width = 100%,
    live: boolean = false,
    tone: Color   = { this.$provided("theme").body },
    lead: number  = 1.6,
    layout: SimpleLayout [ axis = y, spacing = 14 ],
    md: Markdown [ width = 100%, lineHeight = { classroot.lead }, bodyColor = { classroot.tone }, fontScale = { this.root.fontScale }, dark = { this.root.darkUI },
        visible = { this.$data(["md"]) != "" }, text = { this.$data(["md"]) },
        onLink(href: string) { this.root.openDocLink(href) }
        ],
    RunIsland [ datapath = :code[], width = 100%, live = { classroot.live } ]
    ]


/*
## The class page

One class's whole detail page. A single instance exists — the use site
(refCol, below) computes the selected class's model node as its datapath, so
switching classes re-roots this subtree and constructs exactly the page being
read, and a boot never pays for the pages it is not showing.
*/

class ClassDetail extends View [ width = 100%,
    cname: string = "",
    visible = { this.root.selected == classroot.cname },

    // this page is on screen — the gate every inline preview reads before it mounts

    pageLive: boolean = { this.root.mode == "reference" && this.root.selected == classroot.cname },
    hasBase:  boolean = { this.$data(["extends"]) != null },
    layout: SimpleLayout [ axis = y, spacing = 36 ],

    // the ancestor projections as DECLARED data (the value-root idiom), so the
    // chain row and the strips can replicate over them

    ancestry:  Dataset [ contents = { { items: this.root.ancestryOf(classroot.cname) } } ],
    ancestors: Dataset [ contents = { { items: this.root.ancestorsOf(classroot.cname) } } ],

    /* ### Header — the class, where it sits, and its opener */

    header: View [ width = 100%,
        layout: SimpleLayout [ axis = y, spacing = 12 ],
        Eyebrow [ text = { "REFERENCE · " + (this.$data(["origin"]) == "library" ? "STANDARD LIBRARY" : "BUILT-IN") + (this.$data(["source"]) != null ? " · " + this.$data(["source"]) : "") } ],
        Title [ fontSize = { 32 * this.root.fontScale }, text = { classroot.cname } ],

        // the chain, every ancestor a link — and the class's siblings and subclasses

        // (re-rooted to the ancestry data, so its visibility reads the page's fact, not a path)

        chain: View [ width = 100%, visible = { classroot.hasBase },
            datapath = { classroot.ancestry.value },
            layout: WrappingLayout [ spacing = 8, lineSpacing = 8, align = baseline ],
            Mono [ fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").sigDim }, text = { "class " + classroot.cname + " extends" } ],
            Link [ datapath = :items[] ]
            ],
        base: Mono [ fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").sigDim }, visible = { this.$data(["extends"]) == null },
            text = { "class " + classroot.cname + "  (base)" } ],
