    lbl: Mono [ x = 24, y = 6, fontSize = 13, wrap = false,
        text = { classroot.tname },
        textColor = { classroot.lit ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


class TypeGroup extends View [ width = 100%,
    layout: SimpleLayout [ axis = y, spacing = 2 ],
    head: FoldHead [ label = { "" + this.$data(["name"]) },
        contains = { this.root.mode == "type" && (this.$data(["types"])).some(t => t.name == this.root.tname) } ],
    body: View [ width = 100%, visible = { classroot.head.open },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        TypeTab [ datapath = :types[], tname = { "" + this.$data(["name"]) } ],
        g: View [ height = 6 ]
        ]
    ]


// one use of the type: what carries it, of what kind, and the signature or
// default that carries it. The chip is a link wherever the thing has a page.

class UseRow extends View [ width = 100%,
