    // numbered, because the chapters cite each other by number ("chapter 3")

    lbl: Text [ x = 24, y = 8, fontSize = 14, wrap = false,
        text = { classroot.cnum + ". " + classroot.ctitle },
        textColor = { this.root.chapter == classroot.cid ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
    ]


