    pageLive: boolean = { this.root.mode == "guide" && this.root.chapter == classroot.cid },
    layout: SimpleLayout [ axis = y, spacing = 20 ],

    // The chapter's content is its own file (chapters/<id>.json — the
    // extractor's per-chapter projection), fetched when visibility requires
    // it, not at construction — an eager prefetch would make every boot, and
    // every crawl location, pay the whole corpus. `wanted` is a latch: the
    // page being on screen asks for the file, and `loaded` holds the url
    // steady afterward, so a chapter stays resident once landed — switches
    // are instant on return, and nothing ever refetches. A boot costs the
    // model plus exactly one chapter; the other shells stay empty until
    // walked to. The crawl pulls only the location's own chapter through its
    // data resolver; a missing one still fails the build loudly.

    wanted: boolean = { classroot.pageLive || classroot.src.loaded },
    src: DataSource [ auto = true,
        url = { classroot.wanted ? "chapters/" + classroot.cid + ".json" : "" } ],

    loading: Text [ visible = { classroot.src.loading }, fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").textMuted }, text = "Loading the chapter…" ],
    failed:  Text [ visible = { classroot.src.failed }, fontSize = { 14 * this.root.fontScale }, textColor = { this.$provided("theme").textMuted }, wrap = true, width = 100%,
        text = { "The chapter did not load — " + (classroot.src.error || "") } ],

    // the guide is the primary reading surface: brighter body, looser leading (Block defaults)

    content: View [ width = 100%, visible = { classroot.src.loaded }, datapath = { classroot.src.value },
        layout: SimpleLayout [ axis = y, spacing = 20 ],

        Block [ datapath = :segs[], width = 100%, live = { classroot.pageLive } ],

        // a flagship runnable example the chapter opts into with `<!-- demo: <Class> -->`

        demoBox: View [ width = 100%, visible = { this.$data(["demo","length"]) > 0 },
            Example [ datapath = :demo[], width = 100%, live = { classroot.pageLive } ]
            ]
        ],
    tail: View [ width = 100%, height = 60 ]
    ]


/*
## The font-size stepper

Three differently-sized "A"s — small · reset · large. Each cell is a centered
"A" whose glyph size signals the action: the small A shrinks, the middle A
resets to the default, the large A grows. The glyphs are fixed (not
`* app.fontScale`) so the control itself never zooms. Every doc `fontSize`
reads `{ N * app.fontScale }` (and Markdown takes `scale`), so one attribute
zooms the whole document.
*/

class SizeBtn extends View [ width = 32, height = 30, cornerRadius = 6,
    glyph: number = 14,
    delta: number = 0,          // delta 0 = reset to the default
    fill = { this.hovered ? this.$provided("theme").control : null },
    onClick() { this.root.fontScale = classroot.delta == 0 ? 1.0
                    : Math.max(0.7, Math.min(1.6, Math.round((this.root.fontScale + classroot.delta) * 100) / 100)) },
    lbl: Text [ fontWeight = semibold,
        fontSize = { classroot.glyph }, textColor = { this.$provided("theme").textMuted }, text = "A",
        x = center, y = center ]
    ]


/*
## Search results

One hit on the search page: title (the chapter or the member's full name), a
kind crumb, then the matched text in context with the terms bolded — the
snippet arrives pre-built from `findDocs` (the match window is computed once
per query there, not per row render). Click navigates: a result is a location
write, so it deep-links and back-buttons like any rail tab.

Every row is a focus stop — ↓ from the search field walks into the list (the
field genuinely loses focus; the house FocusRing rides the selection), ↓/↑
walk rows, ↑ off the top hands focus back to the field, Return opens the
focused row, Escape clears the search. `app.searchSel` mirrors the focused
index (onFocus writes it) so the selection highlight and the field's ↓ have
one fact to read.
*/

class SearchHit extends View [ width = 100%, cornerRadius = 8,
    loc: string = { this.$data(["loc"]) },
    idx: number = { this.$data(["i"]) },
    focusable = true,
    fill = { this.root.searchSel == this.idx ? this.$provided("theme").sel : this.hovered ? this.$provided("theme").control : null },
    onClick() { this.root.openResult(classroot.loc) },
    onFocus() { this.root.searchSel = this.idx },
    onKeyDown(e: KeyEvent) {
        if (e.key == "ArrowDown") this.root.focusHit(classroot.idx + 1)
        else if (e.key == "ArrowUp") {
            if (classroot.idx == 0) { this.root.searchSel = -1; Focus.focus(this.root.bar.search.field) }
            else this.root.focusHit(classroot.idx - 1)
            }
        else if (e.key == "Enter") this.root.openResult(classroot.loc)
        else if (e.key == "Escape") this.root.dismissSearch()
        },

    // the row's own content box, trailing space included — so the row
    // auto-sizes to exactly its text plus the inset around it

    padding = [9, 12, 9, 12],
    layout: SimpleLayout [ axis = y, spacing = 3 ],
    row: View [ width = 100%, height = 18,
        layout: SimpleLayout [ axis = x, spacing = 10 ],
        Title [ fontSize = 14, wrap = false, text = { this.$data(["title"]) } ],
        Mono [ y = 3, fontSize = 10, letterSpacing = 0.6, textColor = { this.$provided("theme").eyebrow }, wrap = false, text = { this.$data(["crumb"]) } ]
        ],
    snip: Markdown [ width = 100%, fontScale = 0.92, lineHeight = 1.45,
        bodyColor = { this.$provided("theme").refDim }, dark = { this.root.darkUI },
        visible = { this.$data(["snip"]) != "" }, text = { this.$data(["snip"]) } ]
    ]


/*
## The app

A top chrome bar (the house header — brand · search · type-size + theme), a
left rail below it, and a scrolling detail pane, over the model.
*/

App [ fill = { this.$provided("theme").bg }, appName = "Declare Docs",

    // the two faces, named once: the UI face is provided from here, so every
    // run below — the rail, the chrome, the prose — reads it unless it names
    // the monospace face the reference and the code blocks use

    fontFamily = ["system-ui", "sans-serif"],
    mono: Font [ family = "ui-monospace, SFMono-Regular, monospace" ],

    /* Navigation is one string — `location`, the URL fragment. The grammar is
       this app's own: `<mode>/<cursor>[@heading]` (`guide/04-tree`,
       `reference/Slider`, `guide/04-tree@named-views`). The declared initial is the
       default, so a fresh `docs.declare` shows the first guide chapter with a clean
       URL. mode/chapter/selected derive from it and are never assigned — every
       tab and link writes `location`, back/forward writes it back, state follows
       (the single-writer rule; assigning derived state would disconnect history). */

    location = "guide/01-thinking-in-declare",

    /* Cross-mode memory (not a language feature — three plain remembered cursors).
       `location` only carries the active mode's cursor, so switching guide↔reference
       would forget the other side. The navigation verbs keep these in step and the
       mode switch consults them, so returning to a mode lands where you left it. */

    guideAt: string = "01-thinking-in-declare",              // last guide chapter visited …
    refAt:   string = "View",                  // … and last reference class
    formAt:  string = "",                      // … and last language form ("" = the index)
    typeAt:  string = "Color",                 // … and last type page

    // The three navigation verbs every tab, chip and link calls: remember the
    // cursor for its mode, write the location, start the new page at its top.
    // A view that calls one also declares the same reference as its `link`,
    // so the crawler sees the edge and ⌘-click works; the handler runs first,
    // then the follow.

    goGuide(id: string)  { this.root.guideAt = id;   this.root.location = "guide/" + id;     this.root.showPage() },
    goRef(name: string)  { this.root.refAt = name;   this.root.location = "reference/" + name; this.root.showPage() },
    goForm(slug: string) { this.root.formAt = slug;  this.root.location = "language/" + slug; this.root.showPage() },
    goType(name: string) { this.root.typeAt = name;  this.root.location = "type/" + name;     this.root.showPage() },

    // …and the one verb a generated link calls, since a link's target names its
    // own mode: the model hands out locations ("type/Color", "reference/View"),
    // never a verb to guess at.

    goLoc(loc: string) {
        const mode = loc.split("/")[0], cursor = loc.split("/")[1]
        if (mode == "type") this.root.goType(cursor)
        else if (mode == "language") this.root.goForm(cursor)
        else if (mode == "guide") this.root.goGuide(cursor)
        else this.root.goRef(cursor)
        },

    // The active view, parsed out of `location` (the anchor stripped first — it
    // selects a viewpoint, not a page). The inactive mode's cursor falls back to its
    // remembered value, so its rail/selection stay put behind the other mode.

    page:     string = { this.root.location.split("@")[0] },                 // the location less its anchor — the fold heads' key
    mode:     string = { this.root.page.split("/")[0] || "guide" },
    chapter:  string = { this.root.mode == "guide" ? (this.root.page.split("/")[1] || "01-thinking-in-declare") : this.root.guideAt },
    selected: string = { this.root.mode == "reference" ? (this.root.page.split("/")[1] || "View") : this.root.refAt },
    form:     string = { this.root.mode == "language" ? (this.root.page.split("/")[1] || "") : this.root.formAt },
    tname:    string = { this.root.mode == "type" ? (this.root.page.split("/")[1] || this.root.typeAt) : this.root.typeAt },

    // a form's display name, for a related-forms chip

    formName(slug: string) -> string {
        const pages = (this.root.docs.read(["forms", "pages"]) || {})
        return pages[slug] != null ? "" + pages[slug].name : slug
        },

    /* ## Typed signatures
       The model's link index: a printed type name → the location that
       documents it (a type page, or a class page for a component type), plus
       the token-list spelling a named enum prints as. One lookup answers for
       every signature the reference renders, and a name the index does not
       carry answers "" — which is what keeps an unlinkable type rendering
       exactly as it always did instead of becoming a dead link. */

    tindex: object = { this.root.docs.read(["types", "index"]) || ({}) },

    typeLoc(s: string) -> string {
        const idx = this.root.tindex
        const u = idx.unions != null ? idx.unions["" + s] : null
        if (u != null) return "" + u
        const n = idx.link != null ? idx.link["" + s] : null
        return n != null ? "" + n : ""
        },

    // a whole signature, split into runs: each identifier that names a page
    // carries its location, everything between them carries "". A signature
    // that resolves whole (an attribute's type) stays one run, so nothing about
    // its rendering changes.

    typeParts(s: string) -> array {
        const text = "" + s
        const whole = this.root.typeLoc(text)
        if (whole != "") return [({ i: 0, t: text, to: whole })]
        const out = []
        let i = 0
        for (const p of text.split(/([A-Za-z_$][A-Za-z0-9_$]*)/)) {
            if (p == "") continue
            out.push({ i: i, t: p, to: /^[A-Za-z_$]/.test(p) ? this.root.typeLoc(p) : "" })
            i++
        }
        return out
        },

    fontScale: number = 1.0,                   // reader font-size zoom for the CONTENT pane (the A stepper drives it; nav is fixed)
    themeMode: string = "auto",                // "light" | "auto" | "dark" — the ☀◐☾ switch; auto follows app.dark
    barH: number = 52,                         // the house chrome bar (Viewer/Calendar/Tracker share the height)
    compact: boolean = { this.root.width < 780 },    // narrow bar: the type-size stepper stands down so the pill keeps its room

    /* ## Search
       The header pill searches the whole corpus — guide and reference — over
       `search-index.json`, the extractor's flat plain-text projection (one
       entry per chapter and per documented member). The index is fetched on
       the first keystroke, never at boot (the demand-loading contract), and
       `loaded` latches the url so it stays resident. `searchHits` derives
       from the query — typing is searching — and the overlay shows while the
       query is non-empty. A result click is a location write. */

    searchQ: string = "",
    searchSel: number = -1,                    // the focused result row (-1 = the field itself holds focus)
    searchIdx: DataSource [ auto = true,
        url = { this.root.searchQ != "" || this.loaded ? "search-index.json" : "" } ],
    searchHits: array = { this.root.findDocs(this.root.searchQ, this.root.searchIdx.value) },
    hits: Dataset [ contents = { { items: this.root.searchHits } } ],   // the same list as declared data — the results page's cursor root (the navSource idiom)

    /* ## The class page's projections
       The model stays normalized — inherited members are never copied into
       each class — so the page computes its ancestor views here, from the
       tree, per selection: the ancestry as links, each ancestor's strip
       (names, types, signatures, its one-line lead, its own reads), and a
       label's words for the wrapping chip. */

    classNode(name: string) -> object { return (this.root.docs.read(["tree"]) || []).find((c) => c.name == name) || null },

    ancestryOf(name: string) -> array {
        const me = this.root.classNode(name)
        return me == null ? [] : me.chain.slice(1).map((n, i) => ({ name: n, arrow: i > 0 }))
        },

    ancestorsOf(name: string) -> array {
        const me = this.root.classNode(name)
        if (me == null) return []
        return me.chain.slice(1).map((id) => this.root.classNode(id)).filter((c) => c != null).map((c) => ({
            name: c.name, lead: this.root.plainLead(c.doc || ""),
            reads: c.reads || ({ theme: [], provided: [] }),
            n: c.reads ? c.reads.theme.length + c.reads.provided.length : 0,
            attributes: c.attributes.map((a) => ({ name: a.name, label: a.name + ": " + a.type })),
            methods: c.methods.map((m) => ({ name: m.name, label: m.signature })),
            events: c.events.map((e) => ({ name: e.name, label: e.signature })) }))
        },

    // the first paragraph of a class's prose, as plain text — a strip's one-line lead

    plainLead(md: string) -> string {
        return md.split("\n\n")[0].replace(/\n/g, " ").replace(/\*\*/g, "").replace(/\u0060/g, "").replace(/\*/g, "").replace(/\s*\(docs\/system-design[^)]*\)/g, "").trim()
        },

    hasOverrides(list: array) -> boolean { return (list || []).some((a) => a.overrides != null) },

    // a label's words, each keeping its trailing space, so a run of word chips reads continuously

    wordsOf(label: string) -> array {
        const ws = ("" + label).match(/\S+\s*/g) || [label]
        return ws.map((w, i) => ({ i: i, w: w }))
        },

    // Match + rank + snippet, in one pass per query. Terms AND — every term
    // must appear in title or text. Rank: title prefix > title > body count.
    // The snippet is a word-trimmed window around the first body match, terms
    // bolded for the Markdown row (the snippet text is escaped first, so
    // corpus punctuation cannot leak markup into a result).

    findDocs(q: string, idx: object) -> array {
        const query = ("" + q).trim().toLowerCase()
        const entries = idx != null ? (idx).entries : null
        if (query == "" || entries == null) return []
        const terms = query.split(/\s+/).filter(Boolean)
        const out = []
        for (const e of entries) {
            const tl = e.title.toLowerCase(), xl = e.text.toLowerCase()
            let score = 0, first = -1, ok = true
            for (const t of terms) {
                const ti = tl.indexOf(t), xi = xl.indexOf(t)
                if (ti < 0 && xi < 0) { ok = false; break }
                if (ti >= 0) score += ti == 0 ? 120 : 50
                if (xi >= 0) { score += 10; if (first < 0 || xi < first) first = xi }
            }
            if (!ok) continue
            let snip = ""
            if (first >= 0) {
                let a = Math.max(0, first - 70), b = Math.min(e.text.length, first + 130)
                while (a > 0 && e.text[a - 1] != " ") a--          // trim to word edges
                while (b < e.text.length && e.text[b] != " ") b++
                snip = (a > 0 ? "…" : "") + e.text.slice(a, b) + (b < e.text.length ? "…" : "")
                snip = snip.replace(/([\\\u0060*_[\]<>#|])/g, "\\$1")   // escape before bolding (\u0060 = backtick, an escape so the { } scanner never sees one raw)
                for (const t of terms) {
                    const safe = t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
                    snip = snip.replace(new RegExp(safe, "ig"), (m) => "**" + m + "**")
                }
            }
            out.push({ loc: e.loc, title: e.title, crumb: e.crumb, snip: snip, score: score, i: 0 })
        }
        out.sort((a, b) => b.score - a.score)
        const top = out.slice(0, 40)
        for (let i = 0; i < top.length; i++) top[i].i = i   // the row's index — keyboard walk + selection highlight key on it
        return top
        },

    // A result opens like a rail tab: location write + cursor memory + scroll
    // to top, then the overlay closes (clearing the field directly — the
    // uncontrolled TextInput reset, the tracker's omnibox idiom).

    openResult(loc: string) {
        const mode = loc.split("/")[0], cursor = loc.split("/")[1]
        if (mode == "guide") this.root.goGuide(cursor); else this.root.goRef(cursor)
        this.root.dismissSearch()
        },

    dismissSearch() { this.root.searchQ = ""; this.root.searchSel = -1; this.root.bar.search.field.text = "" },

    // Focus result row `i` — the keyboard walk's one move. The rows are the
    // replicated children of the results column, each carrying its `idx`;
    // focusing one fires its onFocus (which records the selection) and the
    // reveal keeps the walked-to row on screen.

    focusHit(i: number) {
        for (const row of this.root.detail.searchCol.children) {
            if ((row).idx === i) { Focus.focus(row); (row).scrollIntoView("nearest"); return }
        }
        },

    // ⌘K reaches the search pill from anywhere; Escape unwinds an open search.

    keys: Keys [
        onKeyDown(e: KeyEvent) {
            if ((e.meta || e.ctrl) && e.code == "KeyK") { Focus.focus(this.root.bar.search.field) }
            else if (e.key == "Escape" && this.root.searchQ != "") this.root.dismissSearch()
            }
        ],

    // the one resolved fact every color decision reads — the theme record and
    // the Markdown rich-element palette must agree, or an override leaves
    // headings in the OS scheme while the chrome switches

    darkUI: boolean = { this.themeMode == "dark" || (this.themeMode == "auto" && this.root.dark) },

    // the rail is fixed-width chrome: its type does not ride the reading zoom,
    // and the chapter slugs are short by design, so 236 sits snug around them

    railW: number = 236,
    liveCard: string = "",                     // the demo an inline editor is republishing (name) …
    liveSource: string = "",                   // … and its current source — the host recompiles this pair live

    // (app.liveReport — built-in — carries the host's rendered compile report; islands display it)

    /* The whole palette in one provided record, switched by the theme mode
       (`darkUI`, which follows the OS scheme under "auto") — every color
       below reads `theme.<token>`, so the docs render dark or light and
       follow the system theme as it flips. */

    // The house preset extended, not replaced: the standard tokens underneath,
    // this app's own values over them, and its many domain names (chipBg, rail,
    // live, errBar …) alongside. A standard control dropped in here finds every
    // token it consults; the docs palette is untouched. `live`/`liveInk` are
    // the editable-example amber and its letters, the same in both modes.

    theme = { { ...(this.darkUI ? SanFranciscoDark : SanFrancisco), ...this.root.docsTokens(this.darkUI) } },

    docsTokens(dark: boolean) -> object { return dark
        ? ({ bg: 0x0B141B, rail: 0x0D1922, surface: 0x0C1620, chipBg: 0x14232E, control: 0x152633, sel: 0x1C2D39, mchipBg: 0x172436, echipBg: 0x241F12, chipHov: 0x1C3243, line: 0x1E313C, rule: 0x345B84, edge: 0x1B2C39, accent: 0x4C8DFF, accentSecondary: 0x37E0C8, chipTeal: 0x9FD9CE, chipBlue: 0xA9C7FF, chipAmber: 0xE7C98A, text: 0xE7EEF2, body: 0xC4CFD8, code: 0xC7D3DC, strong: 0xB7C6D2, mtail: 0x9FB3C2, tabIdle: 0x9BB0BE, refDim: 0x98A7B1, textMuted: 0x8A9BA6, sigDim: 0x6E8494, eyebrow: 0x55707F, live: 0xE6B450, liveInk: 0x1A1A1A, errBg: 0x2A1518, errBar: 0xE0525E, errText: 0xF2A0A6 })
        : ({ bg: 0xF6F8FA, rail: 0xECF0F4, surface: 0xFFFFFF, chipBg: 0xE9EFF4, control: 0xE4EBF1, sel: 0xDBE5EE, mchipBg: 0xE7EDF6, echipBg: 0xF5EFE0, chipHov: 0xD9E4ED, line: 0xDCE3E9, rule: 0xB6C8DA, edge: 0xE0E6EC, accent: 0x2E6FE0, accentSecondary: 0x12A594, chipTeal: 0x15806E, chipBlue: 0x3355C2, chipAmber: 0x8F6F28, text: 0x172530, body: 0x2E3B46, code: 0x2B3843, strong: 0x3A4A56, mtail: 0x4F5F6B, tabIdle: 0x55636F, refDim: 0x51606C, textMuted: 0x6A7883, sigDim: 0x84929D, eyebrow: 0x93A0AA, live: 0xE6B450, liveInk: 0x1A1A1A, errBg: 0xFBE9EA, errBar: 0xC93B47, errText: 0x8E2830 }) },

    /* Code-vs-prose coherence, matching the source-viewer reader: prose (and
       every non-code block) wraps to a reading measure while code fills the
       column — so code renders wider than prose — and every code block gets a
       tinted box with a teal left bar. All provided, so every
       Markdown/HTMLText below inherits it. */

    richTextLayout = { { default: { maxWidth: 560 * this.root.fontScale }, code: { maxWidth: 0 } } },
    codeBackground = { this.$provided("theme").chipBg },
    codeRule = { this.$provided("theme").accentSecondary },

    docs: DataSource [ url = "../../docs/declare-model.json" ],
    datapath = { this.docs.value },                 // root every :path below into the model
    onInit() { this.docs.fetch() },            // DataSource is explicit-fetch — kick it once, on construction

    /* The `declare-docs:` resolver — this app's packaging of the one symbolic
       link scheme (tools/internal/doc/links.mjs is the registry; the gate keeps
       every target real). Guide and reference IDs navigate in-app; the rest
       resolve by the same mechanical id→path rule the registry generates them
       with, and leave through `navigate`. An ordinary href just navigates. */

    // A page switch starts at the top of the new page — the detail pane keeps its
    // scroll offset otherwise. The reveal target is a zero-size anchor at the pane's
    // very top, not the column: the column sits 40px into the pane, so aligning its
    // top with the viewport would eat that margin. Every switch path routes through
    // here: rail tabs and prose links alike.

    showPage() { this.detail.top.scrollIntoView() },

    // An in-app doc link is a location write — it navigates the app exactly like
    // a rail tab, so it deep-links, shares, and back-buttons. It also keeps the
    // remembered cursor in step (like the tabs). External schemes still leave
    // through `navigate`.

    openDocLink(href: string) {
        if (!href.startsWith("declare-docs:")) { this.root.navigate(href); return }
        const id = href.slice("declare-docs:".length)
        if (id.startsWith("guide:")) {                       // guide:tree → the chapter whose id ends with the slug
            const slug = id.slice("guide:".length)
            const hit = (this.root.docs.read(["guide"]) || []).find(c => c.id.replace(/^\d+-/, "") == slug)
            if (hit) this.root.goGuide(hit.id)
            return
        }
        if (id == "reference:index") { this.root.goRef(this.root.refAt); return }
        if (id.startsWith("language:")) { this.root.goForm(id.slice("language:".length)); return }   // language:class → the form's page ("language:" alone → the index)
        if (id.startsWith("type:")) { this.root.goType(id.slice("type:".length)); return }           // type:Motion → the type's page
        if (!id.includes(":")) { this.root.goRef(id.split(".")[0]); return }                      // a reference symbol: View / View.width
        if (id.startsWith("operational:")) { this.root.navigate("docs/operational/" + id.slice("operational:".length) + ".md"); return }
        if (id == "spec:core") { this.root.navigate("docs/declare.md"); return }
        if (id == "essay:why-declare") { this.root.navigate("apps/homepage/homepage.declare") }
        },

    /* ## The chrome bar
       The house header — Viewer's and Tracker's bar, on this app: brand at 20
       (gradient "Declare", solid "Docs"), the search pill centered, and the
       type-size stepper + theme switch on the right. */

    bar: View [ x = 0, y = 0, width = { this.root.width }, height = { this.root.barH }, fill = { this.$provided("theme").rail },
        hair: View [ x = 0, y = { this.root.barH - 1 }, width = 100%, height = 1, fill = { this.$provided("theme").edge } ],

        brand: View [ x = 20, y = { (this.root.barH - 22) / 2 }, height = 22,
            layout: SimpleLayout [ axis = x, spacing = 5 ],

            // "Declare" is the way home — navigate() resolves against the
            // distro root, so this works on either host at any mount point

            Text [ fontSize = 18, fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                textFill = { gradient("90deg", this.$provided("theme").accent, this.$provided("theme").accentSecondary) }, text = "Declare",
                onClick() { this.root.navigate("apps/homepage/homepage.declare") }
                ],
            Text [ fontSize = 18, fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                textColor = { this.$provided("theme").text }, text = "Docs" ]
            ],

        // the pill: search-as-you-type over the whole corpus; Enter opens the
        // first hit; ⌘K focuses it from anywhere (the Keys source above)

        /* The pill is a View; the input lives in its flat zone. TextInput's
           `padding` is uniform (16px of it would crush a 32px field), so the
           capsule shape and the text inset split: the wrapper draws the
           chrome — surface fill, the themed line that turns accent while the
           field inside holds focus — and the field starts exactly where the
           cap ends (x = the 16px radius), transparent chrome of its own.
           The field's own fill stays the surface tone (it paints only inside
           the flat zone, so its square corners are invisible) because the
           editable's colorScheme derives from its view's fill — that is what
           keeps the native caret and placeholder legible in dark. */

        /* The pill centers in the window but never collides: its span is the
           gap between the brand and whatever the right cluster starts with
           (measured off those views, not a breakpoint — a longer brand or a
           wider stepper moves the bound by itself), and the centered x is
           clamped into that gap. Below `compact` the stepper stands down (the
           reading zoom is the most droppable control; the theme switch and the
           search are not), which is what keeps the pill usable at 560. */

        search: View [ y = { (this.root.barH - 32) / 2 }, height = 32, cornerRadius = 16,
            lo: number = { parent.brand.x + parent.brand.width + 16 },
            hi: number = { (this.root.compact ? parent.themeSwitch.x : parent.size.x) - 16 },
            x = { Math.max(this.lo, Math.min((this.root.width - this.width) / 2, this.hi - this.width)) },
            width = { Math.max(120, Math.min(440, this.hi - this.lo)) },
            fill = { this.$provided("theme").surface },
            stroke = { stroke(1, this.field.focused ? this.$provided("theme").accent : this.$provided("theme").line) },
            field: TextInput [ x = 16, y = 1, width = { parent.width - 32 }, height = { parent.height - 2 },   // 1px in from the wrapper's stroke, or the field's fill paints over it
                fill = { this.$provided("theme").surface }, stroke = null, cornerRadius = 0, padding = 0,
                fontSize = 16, textColor = { this.$provided("theme").text },   // 16: a field under it makes iOS zoom the page toward it
                placeholder = "Search the docs…   ⌘K",
                onInput(t: string) { this.root.searchQ = "" + t; this.root.searchSel = -1 },
                onEnter() { if (this.root.searchHits.length > 0) this.root.openResult(this.root.searchHits[0].loc) },
                onKeyDown(e: KeyEvent) {
                    if (e.key == "Escape") this.root.dismissSearch()
                    else if (e.key == "ArrowDown" && this.root.searchHits.length > 0) this.root.focusHit(0)
                    }
                ]
            ],

        size: View [ y = { (this.root.barH - 30) / 2 }, x = { parent.themeSwitch.x - this.width - 20 }, height = 30,
            visible = { !this.root.compact },
            width = { this.contentWidth },
            cornerRadius = 8, fill = { this.$provided("theme").surface }, stroke = { stroke(1, this.$provided("theme").line) },
            layout: SimpleLayout [ axis = x, spacing = 0 ],
            SizeBtn [ glyph = 11, delta = -0.1 ],
            d1: View [ width = 1, height = 18, y = 6, fill = { this.$provided("theme").line } ],
            SizeBtn [ glyph = 15, delta = 0 ],
            d2: View [ width = 1, height = 18, y = 6, fill = { this.$provided("theme").line } ],
            SizeBtn [ glyph = 19, delta = 0.1 ]
            ],

        // the theme switch — light · follow the system · dark. Selection is one
        // App attribute (`themeMode`); the theme record derives from it, so the
        // whole app (and every island's chrome) reskins from this row.

        // light / dark: shows the appearance in force, a press flips it; until
        // then `themeMode` stays "auto" and the OS decides

        themeSwitch: AppearanceSwitch [ y = { (this.root.barH - this.height) / 2 }, x = { this.root.width - this.width - 16 },
            dark = { this.root.darkUI },
            input(v: boolean) { this.root.themeMode = v ? "dark" : "light" }
            ]
        ],

    /* ## The left rail
       Below the bar: the Guide/Reference switch, then the nav for the live
       mode. */

    rail: View [ x = 0, y = { this.root.barH }, width = { this.root.railW }, height = { this.root.height - this.root.barH }, scrolls = y, fill = { this.$provided("theme").rail },
        edge: View [ x = { this.root.railW - 1 }, y = 0, width = 1, height = 100%, fill = { this.$provided("theme").edge } ],
        col: View [ x = 16, y = 16, width = { this.root.railW - 32 },
            layout: SimpleLayout [ axis = y, spacing = 4 ],

            // Guide / Reference — a full-width segmented pair, each tab half the
            // rail, at the rail's own fixed type size. The pair's value is
            // `app.mode`, deriving from `app.location`, so a pick writes the
            // location and the value comes back round — the single source of
            // truth the location comment above asks for.

            // Two tabs. The language pages are a third mode (their own locations,
            // `language/<form>`) but not a third tab: they live at the top of the
            // reference rail, so the Reference tab lights for both.

            modes: Segmented [ width = 100%, height = 30,
                value = { this.root.mode == "guide" ? "guide" : "reference" },
                input(v: object) { if (("" + v) == "guide") this.root.goGuide(this.root.guideAt); else this.root.goRef(this.root.refAt) },

                // each half declares where it goes, so the switch is a link the
                // crawler can follow — without it the reference half of the docs
                // is unreachable from the default location (see SegmentedItem)

                choices = { [ ({ id: "guide",     label: "Guide",     location: "guide/" + this.root.guideAt }),
                              ({ id: "reference", label: "Reference", location: "reference/" + this.root.refAt }) ] }
                ],

            // guide nav — the parts, each a fold over its chapters

            guideNav: View [ width = 100%, visible = { this.root.mode == "guide" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                g1: View [ height = 10 ],
                PartGroup [ datapath = :guideParts[] ]
                ],

            // reference nav — the language (the forms, by group, with the index
            // above them), then the TYPES (the vocabulary a signature prints:
            // model.types.groups), then the classes (by topic:
            // model.classGroups). Each group folds. Types sit on the language
            // side because that is what they are — the words the grammar and
            // every signature are written in, not components you instantiate —
            // and they keep their own eyebrow so a page with tokens and members
            // is never mistaken for a form with syntax and rules.

            refNav: View [ width = 100%, visible = { this.root.mode == "reference" || this.root.mode == "language" || this.root.mode == "type" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                g1:    View [ height = 14 ],
                langEyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.$provided("theme").textMuted }, text = "LANGUAGE" ],
                g2:    View [ height = 4 ],
                idx: View [ width = 100%, height = 28, cornerRadius = 6,
                    lit: boolean = { this.root.mode == "language" && this.root.form == "" },
                    fill = { this.lit ? this.$provided("theme").sel : this.hovered ? this.$provided("theme").control : null },
                    link = "#language/",
                    onClick() { this.root.goForm("") },
                    Text [ x = 24, y = 6, fontSize = 14, wrap = false, text = "All forms", textColor = { parent.lit ? this.$provided("theme").text : this.$provided("theme").tabIdle } ]
                    ],
                FormGroup [ datapath = :forms.groups[] ],
                g3:    View [ height = 18 ],
                typeEyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.$provided("theme").textMuted }, text = "TYPES" ],
                g3b:   View [ height = 4 ],
                TypeGroup [ datapath = :types.groups[] ],
                g3c:   View [ height = 18 ],
                classEyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.$provided("theme").textMuted }, text = "CLASSES" ],
                g4:    View [ height = 4 ],
                ClassGroup [ datapath = :classGroups[] ],

                // the rail's own bottom margin: the last class group ends 24
                // above the fold, matching the 16 the column starts with

                tail:  View [ height = 24 ]
                ]
            ]
        ],

    /* ## The detail pane
       Its own scroller. Guide chapters are light shells (each fetches and
       builds its content only once visibility asks — ChapterDetail); the
       reference is one page, re-rooted to the selection (refCol). So the
       scroller only ever measures what is actually being read.
       `selectable` (a provided value) opts the whole right pane into ordinary
       browser text selection — prose, signatures, Markdown runs — while the
       rail stays chrome.

       Search replaces the content: while the query is non-empty the reading
       column hides and the results page takes the pane — same column, same
       scroller, no overlay chrome. Clearing the query (Escape, opening a
       result, deleting the text) brings the page back exactly as it was:
       `visible` conceals, it never tears down. No matches (or the index still
       loading) says so in the middle of the pane. */

    detail: View [ x = { this.root.railW }, y = { this.root.barH }, width = { this.root.width - this.root.railW }, height = { this.root.height - this.root.barH }, scrolls = y, selectable = true,

        // the reading margins are the pane's own content box, so every column
        // in it is simply the room it is given

        padding = [0, 48, 0, 48],
        top: View [ x = 0, y = 0, width = 1, height = 1 ],       // showPage's scroll-to-top anchor
        col: View [ y = 40, width = 100%, visible = { this.root.searchQ == "" },
            guideCol: View [ width = 100%, visible = { this.root.mode == "guide" },
                ChapterDetail [ datapath = :guide[], cid = :id ]
                ],

            /* One reference page exists at a time — the selection's. The
               datapath computes the selected class's node, so a switch
               re-roots this single subtree and builds just that page, and a
               boot never constructs the hundreds it is not showing; the rail
               (ClassTab, above) still replicates the full list — that is what
               visibility requires of a navigator. */

            refCol: View [ width = 100%, visible = { this.root.mode == "reference" },
                ClassDetail [ datapath = { (this.root.docs.read(["tree"]) || []).find(c => c.name == this.root.selected) }, cname = :name ]
                ],

            // the language pane: the index (no cursor) or ONE form's page, re-rooted to
            // the selection exactly as the reference page is

            langCol: View [ width = 100%, visible = { this.root.mode == "language" },
                FormIndex [ datapath = { this.root.docs.read(["forms"]) } ],
                FormDetail [ datapath = { ((this.root.docs.read(["forms", "pages"]) || {}))[this.root.form] }, slug = { "" + this.$data(["slug"]) } ]
                ],

            // the type pane — ONE page, re-rooted to the selection, exactly as
            // the reference and language panes are

            typeCol: View [ width = 100%, visible = { this.root.mode == "type" },
                TypeDetail [ datapath = { ((this.root.docs.read(["types", "pages"]) || {}))[this.root.tname] }, tname = { "" + this.$data(["name"]) } ]
                ]
            ],

        // the results page — rows replicate off the computed hits (the
        // homepage's value-root + :items[] idiom); focusHit walks these
        // children, so this column is the one place rows live

        searchCol: View [ y = 24, width = 100%,
            visible = { this.root.searchQ != "" && this.root.searchHits.length > 0 },
            layout: SimpleLayout [ axis = y, spacing = 2 ],
            datapath = { this.root.hits.value },
            SearchHit [ datapath = :items[], width = 100% ]
            ],

        // the empty answer, centered in the pane — visible only once the
        // index has answered (before that, the honest "loading")

        noHits: View [ visible = { this.root.searchQ != "" && this.root.searchHits.length == 0 },
            x = 0, y = 0, width = 100%, height = 100%,
            msg: Muted [ x = center, y = center, fontSize = 14,
                text = { this.root.searchIdx.loaded ? "No matches — the corpus has nothing for “" + this.root.searchQ + "”." : "Loading the search index…" } ]
            ]
        ]
    ,
    // the traveling focus indicator — provided with the component library

    FocusRing [ ],

    // the tooltip singleton — provided with the component library (tip = attribute)

    Tooltip [ ],
]
